//! The grass's pipelines and draws (renderer pass 2 A.8; `crate::foliage`): built-in pipelines
//! of its own over the forward frame group, the pass view and the grass group (group 2), the
//! blades generated by compute after the frame's tables (graph node 1) and drawn in three nodes:
//!
//! - **Shadows (node 6)**: on qualities that cast, the camera's blades into the nearest cascade
//!   (two-sided, the casters' bias and pancaking as every caster's).
//! - **Prepass (node 7)**: depth and the blade's normal turned to the viewer, with the sway's own
//!   motion on frames writing motion (the motion node's group at group 3), so AO, contact shadows,
//!   the sun mask and TAA see the meadow.
//! - **Opaque (node 12)**: the blades lit like every built-in surface plus the light through them,
//!   after the terrain, `Equal` against the prepass depth where the world pass reuses it.
//!
//! The grass belongs to the terrain (its layers carry it): a frame without a terrain, without a
//! grassy layer or on a quality without grass draws, compiles and costs what it did before.

use wgpu::{RenderPass, RenderPipeline, TextureFormat};

use super::{FramePrep, FramePrepass, Renderer, ScenePath, SurfaceKey, depth_state, shader, surface_constants};
use crate::compile::Compiled;
use crate::error::RenderError;
use crate::foliage::GrassQuality;
use crate::foliage::gpu::{FORWARD_ENTRIES, GRASS, GRASS_MOTION_GROUP, GRASS_SHADOW, GrassFrameInput, GrassGpu, MOTION_ENTRIES, PREPASS_ENTRIES, SHADOW_VERTEX_ENTRY};
use crate::settings::ShadowFormat;
use crate::settle::HistorySet;
use crate::shadow::{CASTER_CONSTANT_BIAS, CASTER_SLOPE_BIAS, CasterDepth, DEPTH16_UNIT};
use crate::tables::pipeline_layout;

/// What the world pass's grass pipeline is made for.
#[derive(Clone, Copy, Debug, PartialEq)]
struct WorldKey {
    format: TextureFormat,
    reversed: bool,
    samples: u32,
    surface: SurfaceKey,
    /// Whether the world pass tests `Equal` against the prepass depth (which holds the blades).
    equal: bool,
}

/// What the prepass's grass pipeline is made for.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PrepassKey {
    reversed: bool,
    motion: bool,
}

/// The grass's pipelines (made on the first frame that draws each, dropped with the grass) and
/// the simulated time its wind sways at.
#[derive(Default)]
pub(super) struct GrassPipelines {
    world: Option<(WorldKey, Compiled<RenderPipeline>)>,
    prepass: Option<(PrepassKey, Compiled<RenderPipeline>)>,
    /// The casters into `depth32float` and `depth16unorm` maps.
    casters: Option<[Compiled<RenderPipeline>; 2]>,
}

/// The simulated time the grass (and, in a clock of its own, model wind) sways at: the next
/// frame's seconds and each history set's last frame's (its motion sways from there).
#[derive(Clone, Copy, Debug, Default)]
pub(super) struct GrassTime {
    seconds: f32,
    /// Live's and a settled capture's last frame's seconds.
    last: [Option<f32>; 2],
}

impl GrassTime {
    /// This frame's seconds and last frame's on history set `set` (this frame's on a history
    /// reset: no sway of its own), remembered for the next frame.
    pub(super) fn advance(&mut self, set: HistorySet, reset: bool) -> [f32; 2] {
        let at = usize::from(set != HistorySet::Live);
        let before = if reset { self.seconds } else { self.last[at].unwrap_or(self.seconds) };
        self.last[at] = Some(self.seconds);
        [self.seconds, before]
    }
}

/// What the last frame drew of the grass.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct GrassStats {
    /// Tiles across the generated square.
    pub tiles: u32,
    /// The cell grid's first cell.
    pub origin: [i32; 2],
    /// Vertices a blade.
    pub blade_vertices: u32,
}

/// The parts of a grass pipeline its passes choose.
struct GrassSpec<'a> {
    label: &'a str,
    module: &'a wgpu::ShaderModule,
    entries: (&'a str, &'a str),
    layout: &'a wgpu::PipelineLayout,
    targets: &'a [Option<wgpu::ColorTargetState>],
    depth: wgpu::DepthStencilState,
    samples: u32,
    constants: &'a [(&'a str, f64)],
}

/// Both faces of a strip per blade (non-indexed: each instance its own strip).
const BLADE_PRIMITIVE: wgpu::PrimitiveState =
    wgpu::PrimitiveState { topology: wgpu::PrimitiveTopology::TriangleStrip, strip_index_format: None, front_face: wgpu::FrontFace::Ccw, cull_mode: None, unclipped_depth: false, polygon_mode: wgpu::PolygonMode::Fill, conservative: false };

fn grass_pipeline(device: &wgpu::Device, spec: &GrassSpec<'_>) -> Compiled<RenderPipeline> {
    let options = wgpu::PipelineCompilationOptions { constants: spec.constants, ..Default::default() };
    crate::compile::render_pipeline(device, &wgpu::RenderPipelineDescriptor {
        label: Some(spec.label),
        layout: Some(spec.layout),
        vertex: wgpu::VertexState { module: spec.module, entry_point: Some(spec.entries.0), compilation_options: options.clone(), buffers: &[] },
        primitive: BLADE_PRIMITIVE,
        depth_stencil: Some(spec.depth.clone()),
        multisample: wgpu::MultisampleState { count: spec.samples, ..Default::default() },
        fragment: Some(wgpu::FragmentState { module: spec.module, entry_point: Some(spec.entries.1), compilation_options: options, targets: spec.targets }),
        multiview_mask: None,
        cache: None,
    })
}

impl Renderer {
    /// The simulated seconds the next frames' grass and swaying models sway at (the tick's, never
    /// the wall clock; 0 until set). Their motion sways from the history set's last frame's.
    pub fn set_foliage_seconds(&mut self, seconds: f32) {
        let seconds = if seconds.is_finite() { seconds } else { 0.0 };
        self.grass_time.seconds = seconds;
        self.wind_time.seconds = seconds;
    }

    /// The grass quality frames draw with.
    fn grass_quality(&self) -> GrassQuality {
        self.quality.grass
    }

    /// Make the grass of the terrain just set (`desc`), or drop it (no terrain, or no grassy
    /// layer).
    pub(super) fn set_grass(&mut self, desc: Option<&crate::terrain::TerrainDesc>) -> Result<(), RenderError> {
        self.grass_pipelines = GrassPipelines::default();
        let (Some(desc), Some(terrain)) = (desc, self.terrain.as_ref()) else {
            self.grass = None;
            return Ok(());
        };
        if crate::foliage::densest(desc) <= 0.0 {
            self.grass = None;
            return Ok(());
        }
        self.grass = Some(GrassGpu::new(&self.device, desc, terrain.layout())?);
        Ok(())
    }

    /// What the last frame drew of the grass (None: no grass that frame).
    pub fn grass_stats(&self) -> Option<GrassStats> {
        let (grid, row) = self.grass.as_ref()?.frame()?;
        Some(GrassStats { tiles: grid.tiles, origin: grid.origin, blade_vertices: row.grid[3] as u32 })
    }

    /// The grass on the GPU (tests read its blades back).
    pub fn grass_gpu(&self) -> Option<&GrassGpu> {
        self.grass.as_ref()
    }

    /// The last frame's drawn blades read back from the GPU, in draw order: each blade's record
    /// (`foliage::Blade::pack`). None without grass that frame.
    pub fn read_grass(&self, gpu: &crate::gpu::Gpu) -> Result<Option<Vec<[u32; 4]>>, RenderError> {
        let Some(grass) = self.grass.as_ref().filter(|grass| grass.drawn()) else { return Ok(None) };
        let Some((args, order, regions)) = grass.readback_buffers() else { return Ok(None) };
        let read = |buffer: &wgpu::Buffer, bytes: u64| -> Result<Vec<u32>, RenderError> {
            let staging = crate::readback::stage_buffer(gpu, buffer, 0, bytes)?;
            Ok(bytemuck::pod_collect_to_vec(&crate::readback::map_read_blocking(gpu, &staging, bytes)?))
        };
        let count = u64::from(read(args, 16)?[1]);
        if count == 0 {
            return Ok(Some(Vec::new()));
        }
        let order = read(order, count * 4)?;
        let records = read(regions, regions.size())?;
        Ok(Some(order.iter().map(|at| {
            let i = *at as usize * 4;
            [records[i], records[i + 1], records[i + 2], records[i + 3]]
        }).collect()))
    }

    /// The bytes the grass holds on the GPU (0: none).
    pub(super) fn grass_bytes(&self) -> u64 {
        self.grass.as_ref().map_or(0, GrassGpu::bytes)
    }

    /// This frame's grass row and buffers for `plan`'s camera, and the pipelines `path` and the
    /// frame's `prepass` (motion when `motion`) draw them with.
    pub(super) fn prepare_grass(&mut self, plan: &crate::scene::FramePlan, path: &ScenePath, prepass: Option<&FramePrepass>, motion: bool) -> Result<(), RenderError> {
        let quality = self.grass_quality();
        let reset = self.frame_index == 0 && !self.temporal_kept;
        let seconds = self.grass_time.advance(self.history_set, reset);
        let Some(grass) = self.grass.as_mut() else { return Ok(()) };
        let camera = [plan.frame.camera_pos[0], plan.frame.camera_pos[1], plan.frame.camera_pos[2]];
        let pixel = crate::foliage::gpu::pixel_at_unit_depth(&plan.frame.view_proj, self.targets.render_size.1);
        let input = GrassFrameInput { camera, planes: plan.cull_views.planes[0], seconds, pixel };
        grass.prepare(&self.device, &self.queue, &quality, &input)?;
        if !grass.drawn() {
            return Ok(());
        }
        let surface = self.surface_key(path.hdr);
        let world = WorldKey { format: path.format, reversed: path.depth_reversed, samples: self.samples, surface, equal: prepass.is_some_and(|prepass| prepass.equal) };
        if self.grass_pipelines.world.as_ref().is_none_or(|(made, _)| *made != world) {
            let pipeline = self.grass_world_pipeline(&world)?;
            self.grass_pipelines.world = Some((world, pipeline));
        }
        if prepass.is_some() {
            let key = PrepassKey { reversed: path.depth_reversed, motion };
            if self.grass_pipelines.prepass.as_ref().is_none_or(|(made, _)| *made != key) {
                let pipeline = self.grass_prepass_pipeline(key)?;
                self.grass_pipelines.prepass = Some((key, pipeline));
            }
        }
        if quality.casts && plan.cascades.is_some() && self.grass_pipelines.casters.is_none() {
            let caster = |format: ShadowFormat| self.grass_caster_pipeline(format.texture_format());
            self.grass_pipelines.casters = Some([caster(ShadowFormat::Depth32)?, caster(ShadowFormat::Depth16)?]);
        }
        Ok(())
    }

    fn grass_layout(&self) -> Result<&wgpu::BindGroupLayout, RenderError> {
        self.grass.as_ref().map(GrassGpu::layout).ok_or_else(|| RenderError::refused(crate::error::RenderCode::MeshInvalid, "grass: none held".to_owned()))
    }

    fn grass_world_pipeline(&self, key: &WorldKey) -> Result<Compiled<RenderPipeline>, RenderError> {
        let module = shader(&self.device, "grass", GRASS)?;
        let layout = pipeline_layout(&self.device, "grass", &[&self.layouts.frame, &self.layouts.pass, self.grass_layout()?]);
        let constants = surface_constants(key.reversed, key.format, key.surface);
        let writes = [Some(wgpu::ColorTargetState { format: key.format, blend: None, write_mask: wgpu::ColorWrites::ALL })];
        let equal = wgpu::DepthStencilState { depth_compare: Some(wgpu::CompareFunction::Equal), ..depth_state(false, key.reversed) };
        Ok(grass_pipeline(&self.device, &GrassSpec {
            label: "grass",
            module: &module,
            entries: FORWARD_ENTRIES,
            layout: &layout,
            targets: &writes,
            depth: if key.equal { equal } else { depth_state(true, key.reversed) },
            samples: if key.equal { 1 } else { key.samples },
            constants: &constants,
        }))
    }

    fn grass_prepass_pipeline(&self, key: PrepassKey) -> Result<Compiled<RenderPipeline>, RenderError> {
        let module = shader(&self.device, "grass", GRASS)?;
        let grass = self.grass_layout()?;
        let motion = self.motion_node.as_ref().filter(|_| key.motion);
        let layout = match motion {
            Some(node) => pipeline_layout(&self.device, "grass motion", &[&self.layouts.frame, &self.layouts.pass, grass, node.layout()]),
            None => pipeline_layout(&self.device, "grass prepass", &[&self.layouts.frame, &self.layouts.pass, grass]),
        };
        let normals = [Some(wgpu::ColorTargetState { format: crate::prepass::NORMALS_FORMAT, blend: None, write_mask: wgpu::ColorWrites::ALL })];
        let all = crate::motion::TARGET_FORMATS.map(|format| Some(wgpu::ColorTargetState { format, blend: None, write_mask: wgpu::ColorWrites::ALL }));
        Ok(grass_pipeline(&self.device, &GrassSpec {
            label: if motion.is_some() { "grass motion" } else { "grass prepass" },
            module: &module,
            entries: if motion.is_some() { MOTION_ENTRIES } else { PREPASS_ENTRIES },
            layout: &layout,
            targets: if motion.is_some() { &all } else { &normals },
            depth: depth_state(true, key.reversed),
            samples: 1,
            constants: &[],
        }))
    }

    /// The casters' pipeline into a `format` map: depth only, both faces of the strip, the
    /// casters' bias (`shadow::caster_pipeline`'s, which culls back faces and draws lists).
    fn grass_caster_pipeline(&self, format: TextureFormat) -> Result<Compiled<RenderPipeline>, RenderError> {
        let module = shader(&self.device, "grass shadow", GRASS_SHADOW)?;
        let layout = pipeline_layout(&self.device, "grass shadow", &[&self.layouts.shadow, &self.layouts.pass, self.grass_layout()?]);
        let unclipped = self.casters == CasterDepth::Unclipped;
        let unit = if format == TextureFormat::Depth16Unorm { DEPTH16_UNIT } else { 0.0 };
        let constants = [
            ("GX_UNCLIPPED_DEPTH", f64::from(u8::from(unclipped))),
            ("GX_SHADOW_DEPTH_UNIT", unit),
            ("GX_SHADOW_BIAS_CONSTANT", f64::from(CASTER_CONSTANT_BIAS)),
            ("GX_SHADOW_BIAS_SLOPE", f64::from(CASTER_SLOPE_BIAS)),
        ];
        let options = wgpu::PipelineCompilationOptions { constants: &constants, ..Default::default() };
        // A fragment that writes its depth gets no hardware bias: `fs_shadow_caster` applies it.
        let bias = if unclipped { wgpu::DepthBiasState { constant: CASTER_CONSTANT_BIAS, slope_scale: CASTER_SLOPE_BIAS, clamp: 0.0 } } else { wgpu::DepthBiasState::default() };
        let fragment = (!unclipped).then(|| wgpu::FragmentState { module: &module, entry_point: Some("fs_shadow_caster"), compilation_options: options.clone(), targets: &[] });
        Ok(crate::compile::render_pipeline(&self.device, &wgpu::RenderPipelineDescriptor {
            label: Some("grass shadow"),
            layout: Some(&layout),
            vertex: wgpu::VertexState { module: &module, entry_point: Some(SHADOW_VERTEX_ENTRY), compilation_options: options, buffers: &[] },
            primitive: wgpu::PrimitiveState { unclipped_depth: unclipped, ..BLADE_PRIMITIVE },
            depth_stencil: Some(wgpu::DepthStencilState {
                format,
                depth_write_enabled: Some(true),
                depth_compare: Some(wgpu::CompareFunction::Less),
                stencil: wgpu::StencilState::default(),
                bias,
            }),
            multisample: wgpu::MultisampleState::default(),
            fragment,
            multiview_mask: None,
            cache: None,
        }))
    }

    /// Record this frame's grass generation into `encoder` (after the tables' uploads). Returns
    /// the compute passes recorded.
    pub(super) fn encode_grass(&self, encoder: &mut wgpu::CommandEncoder) -> u32 {
        let (Some(grass), Some(terrain)) = (self.grass.as_ref(), self.terrain.as_ref()) else { return 0 };
        grass.encode(encoder, terrain.group())
    }

    /// The blades' casters into cascade `cascade`'s map (`pass`, its groups not yet bound): the
    /// nearest cascade only, on qualities that cast.
    pub(super) fn draw_grass_casters(&self, pass: &mut RenderPass<'_>, prep: &FramePrep, cascade: usize) -> u32 {
        let (Some(grass), Some(casters)) = (self.grass.as_ref(), self.grass_pipelines.casters.as_ref()) else { return 0 };
        if cascade != 0 || !self.grass_quality().casts {
            return 0;
        }
        let view = 1 + cascade as u32;
        let at = usize::from(self.shadow_desc.format == ShadowFormat::Depth16.texture_format());
        pass.set_pipeline(&casters[at]);
        pass.set_bind_group(0, &prep.groups.shadow, &[]);
        pass.set_bind_group(1, &prep.groups.pass, &[(u64::from(view) * crate::tables::PASS_VIEW_STRIDE) as u32]);
        grass.draw(pass)
    }

    /// The blades' depth and normals (and motion: `motion` the motion node's group) into the
    /// prepass (`pass`).
    pub(super) fn draw_grass_prepass(&self, pass: &mut RenderPass<'_>, prep: &FramePrep, motion: Option<&wgpu::BindGroup>) -> u32 {
        let (Some(grass), Some((key, pipeline))) = (self.grass.as_ref(), self.grass_pipelines.prepass.as_ref()) else { return 0 };
        if key.motion != motion.is_some() || !grass.drawn() {
            return 0;
        }
        pass.set_pipeline(pipeline);
        pass.set_bind_group(0, &prep.groups.frame, &[]);
        pass.set_bind_group(1, &prep.groups.pass, &[0]);
        if let Some(group) = motion {
            pass.set_bind_group(GRASS_MOTION_GROUP, group, &[]);
        }
        grass.draw(pass)
    }

    /// The blades in the world pass (`pass`) with the frame's `frame` and `pass_views` groups.
    pub(super) fn draw_grass(&self, pass: &mut RenderPass<'_>, frame: &wgpu::BindGroup, pass_views: &wgpu::BindGroup) -> u32 {
        let (Some(grass), Some((_, pipeline))) = (self.grass.as_ref(), self.grass_pipelines.world.as_ref()) else { return 0 };
        if !grass.drawn() {
            return 0;
        }
        pass.set_pipeline(pipeline);
        pass.set_bind_group(0, frame, &[]);
        pass.set_bind_group(1, pass_views, &[0]);
        grass.draw(pass)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_sway_starts_from_this_frame_after_a_reset_and_from_the_last_frame_otherwise() {
        let mut time = GrassTime { seconds: 1.0, ..GrassTime::default() };
        assert_eq!(time.advance(HistorySet::Live, true), [1.0, 1.0], "a reset has no sway of its own");
        time.seconds = 1.5;
        assert_eq!(time.advance(HistorySet::Live, false), [1.5, 1.0]);
        // A settled capture's re-renders of one tick keep Live's last frame.
        assert_eq!(time.advance(HistorySet::Capture, true), [1.5, 1.5]);
        assert_eq!(time.advance(HistorySet::Capture, false), [1.5, 1.5]);
        time.seconds = 2.0;
        assert_eq!(time.advance(HistorySet::Live, false), [2.0, 1.5], "Live resumes from its own last frame");
    }
}

